"""navera_lite/ros/camera_node.py — the live camera of NAVERA Lite, replaying a recorded flight in real time:
it stamps every frame at its exposure, reads the attitude at that instant from the IMU topic with YOUR
timing.attitude_at(), and decides with YOUR timing.usable(). Part of NAVERA Lite, the course's teaching stack
(given in mission 20). Written for the course; it is not NAVERA code.

    python3 -m navera_lite.ros.camera_node                                       the flight, looping
    python3 -m navera_lite.ros.camera_node --ros-args -p latency_s:=0.0         stamp frames at the grab (wrong)
    python3 -m navera_lite.ros.camera_node --ros-args -p queue:=4               a program that lets frames queue

What it replays (/data/academy/20-live-camera/flight/): a survey plane's IMU at 50 Hz (imu.csv) and the frames
of its camera, fixed under the body looking down, 28.8 frames per second (frames.csv: when each frame reached
the program, and the true pose at its exposure). Each frame is drawn from the map (map.jpg, © OpenStreetMap
contributors) with that true pose, so the picture is what the camera saw.

Every 1/rate_hz seconds the node offers ONE frame to vision, like NAVERA's live camera:
  queue = 1  the program grabs every frame as it arrives and keeps only the newest (grab time = its arrival);
  queue = N  a naive program: the driver keeps up to N frames in a first-in-first-out queue (when it is full,
             new frames are lost), and the program takes the oldest one only when it wants a frame, stamping
             it at that moment — the frame has waited in the queue, and the stamp does not know it.
Then: exposure = grab − latency_s; attitude = attitude_at(exposure, IMU history); rate = rotation_rate_dps(…);
(usable, reason) = usable(attitude, rate, settings).

Publishes  navera_lite/imu            sensor_msgs/Imu (the recorded attitude, stamped at its measurement)
           navera_lite/camera/image   sensor_msgs/Image, bgr8, 480 × 270 (the offered frame)
           navera_lite/camera/meta    diagnostic_msgs/DiagnosticStatus: level OK = usable, WARN = refused;
                                      message = the reason; values: META_KEYS (strings)
Subscribes navera_lite/imu (its own replay, or another IMU publisher with -p publish_imu:=false).
Parameters: flight, settings ("camera.yaml"), latency_s (−1 = take it from the settings file), rate_hz (2.0),
queue (1), loop (true), start_s (0.0: where in the flight to start), start_delay_s (1.0), publish_imu (true),
save_dir ("out": the last offered frame as live_frame.jpg and its meta as live_meta.json; "none" = save nothing).
"""
import csv
import json
import math
import os
from collections import deque

import cv2
import numpy as np
from diagnostic_msgs.msg import DiagnosticStatus, KeyValue
from rclpy.node import Node
from sensor_msgs.msg import Image, Imu

from navera_lite.camera import K_from_hfov, camera_rotation
from navera_lite.rotations import q_angle_deg, rpy_human
from navera_lite.ros.convert import s_to_stamp, stamp_to_s
from navera_lite.ros.qos import SENSOR_QOS
from navera_lite.ros.runner import run_node
from navera_lite.timing import exposure_time, load_camera_settings, tilt_deg

FLIGHT_DIR = "/data/academy/20-live-camera/flight"
IMAGE_SIZE = (480, 270)          # width, height of the published frames (pixels); horizontal field of view 60°
META_NAME = "navera_lite/camera"
META_KEYS = ("frame", "grab_s", "exposure_s", "latency_s", "waited_s", "roll_deg", "pitch_up_deg", "heading_deg",
             "tilt_deg", "rate_dps", "usable", "att_err_deg", "queue")


# given — read it and use it, no need to change it
def read_flight(folder=FLIGHT_DIR):
    """The recorded flight: (imu, frames). imu = list of (t_s, (qx, qy, qz, qw)); frames = list of dicts with
    frame, grab_s, east_m, north_m, height_m, q_true (x, y, z, w). Times are seconds of the flight's clock.

    Example: read_flight()[1][0]["frame"] → 0
    """
    imu = []
    with open(os.path.join(folder, "imu.csv"), newline="") as f:
        for r in csv.DictReader(f):
            imu.append((float(r["t_s"]), tuple(float(r[k]) for k in ("qx", "qy", "qz", "qw"))))
    frames = []
    with open(os.path.join(folder, "frames.csv"), newline="") as f:
        for r in csv.DictReader(f):
            frames.append({"frame": int(r["frame"]), "grab_s": float(r["grab_s"]), "east_m": float(r["east_m"]),
                           "north_m": float(r["north_m"]), "height_m": float(r["height_m"]),
                           "q_true": tuple(float(r[k]) for k in ("true_qx", "true_qy", "true_qz", "true_qw"))})
    return imu, frames


# given — read it and use it, no need to change it
class GroundPainter:
    """Draws what the camera saw from the map: map.jpg + map.json of the flight folder (ENU metres from its centre)."""

    def __init__(self, folder=FLIGHT_DIR, size=IMAGE_SIZE, hfov_deg=60.0):
        info = json.load(open(os.path.join(folder, "map.json")))
        self.map = cv2.imread(os.path.join(folder, "map.jpg"))
        if self.map is None:
            raise FileNotFoundError(f"cannot read {folder}/map.jpg")
        g, w, h = info["gsd_m"], info["width_px"], info["height_px"]
        self.enu_from_map = np.array([[g, 0.0, -w / 2 * g], [0.0, -g, h / 2 * g], [0.0, 0.0, 1.0]])
        self.size = size
        self.K = K_from_hfov(hfov_deg, size[0], size[1])

    def draw(self, east_m, north_m, height_m, q):
        """The camera's picture (BGR uint8) for a body attitude q (x, y, z, w) at (east, north, height)."""
        R_wc = camera_rotation(q)
        ground = np.array([[1.0, 0.0, -east_m], [0.0, 1.0, -north_m], [0.0, 0.0, -height_m]])
        H = self.K @ R_wc.T @ ground @ self.enu_from_map
        img = cv2.warpPerspective(self.map, H, self.size, flags=cv2.INTER_LINEAR, borderMode=cv2.BORDER_REPLICATE)
        text = "(c) OpenStreetMap contributors"              # OpenCV's fonts have no © sign
        (w, h), _ = cv2.getTextSize(text, cv2.FONT_HERSHEY_SIMPLEX, 0.35, 1)
        W, Hh = self.size
        cv2.rectangle(img, (W - w - 8, Hh - h - 8), (W - 1, Hh - 1), (255, 255, 255), -1)
        cv2.putText(img, text, (W - w - 4, Hh - 5), cv2.FONT_HERSHEY_SIMPLEX, 0.35, (60, 60, 60), 1, cv2.LINE_AA)
        return img


# given — read it and use it, no need to change it
def nice(v, digits=3):
    """A meta value as a string: None → "none", floats rounded."""
    if v is None:
        return "none"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        return "nan" if math.isnan(v) else f"{v:.{digits}f}"
    return str(v)


# given — read it and use it, no need to change it
class CameraNode(Node):
    """The node "camera" (see the file's header)."""

    def __init__(self):
        super().__init__("camera")
        import navera_lite.timing as timing           # YOUR functions (read once, at start)
        self.timing = timing
        for name, default in (("flight", FLIGHT_DIR), ("settings", "camera.yaml"), ("latency_s", -1.0),
                              ("rate_hz", 2.0), ("queue", 1), ("loop", True), ("start_s", 0.0),
                              ("start_delay_s", 1.0), ("publish_imu", True), ("save_dir", "out")):
            self.declare_parameter(name, default)
        p = {n: self.get_parameter(n).value for n in ("flight", "settings", "latency_s", "rate_hz", "queue", "loop",
                                                       "start_s", "start_delay_s", "publish_imu", "save_dir")}
        self.cfg = load_camera_settings(p["settings"])
        self.latency_s = float(p["latency_s"]) if p["latency_s"] >= 0 else float(self.cfg["latency_s"])
        self.rate_hz, self.queue_len = float(p["rate_hz"]), max(1, int(p["queue"]))
        self.loop, self.publish_imu = bool(p["loop"]), bool(p["publish_imu"])
        self.save_dir = "" if p["save_dir"] in ("", "none") else p["save_dir"]
        self.imu, self.frames = read_flight(p["flight"])
        self.painter = GroundPainter(p["flight"])
        self.duration_s = max(self.frames[-1]["grab_s"], self.imu[-1][0]) + 0.1
        self.start_s = float(p["start_s"])
        self.queue = deque()
        self.offered = 0
        self.pub_imu = self.create_publisher(Imu, "navera_lite/imu", SENSOR_QOS)
        self.pub_img = self.create_publisher(Image, "navera_lite/camera/image", 10)
        self.pub_meta = self.create_publisher(DiagnosticStatus, "navera_lite/camera/meta", 10)
        self.create_subscription(Imu, "navera_lite/imu", self.on_imu, SENSOR_QOS)
        self.t0 = self.now_s() + float(p["start_delay_s"]) - self.start_s    # wall time of the flight's t = 0
        self._restart_lap()
        self.next_offer = self.t0 + self.start_s + 0.5
        self.create_timer(0.005, self.on_tick)
        self.get_logger().info(
            f"camera replay: {len(self.frames)} frames, IMU {len(self.imu)} samples, latency_s {self.latency_s:.3f} s, "
            f"{self.rate_hz:g} frame(s)/s offered, queue {self.queue_len}"
            + ("" if self.publish_imu else " — IMU from another publisher"))

    def now_s(self):
        return self.get_clock().now().nanoseconds * 1e-9

    def _restart_lap(self):
        self.i_imu = next((k for k, s in enumerate(self.imu) if s[0] >= self.start_s), len(self.imu))
        self.i_frame = next((k for k, f in enumerate(self.frames) if f["grab_s"] >= self.start_s), len(self.frames))
        self.queue.clear()
        self.newest = None
        self.hist_t, self.hist_q = [], []

    def on_imu(self, msg):
        o = msg.orientation
        if msg.orientation_covariance[0] == -1.0:
            return                                          # a heartbeat without an attitude (REP-145)
        t = stamp_to_s(msg.header.stamp)
        if self.hist_t and t <= self.hist_t[-1]:
            if t < self.hist_t[-1] - 1.0:                   # the replay restarted: forget the old flight
                self.hist_t, self.hist_q = [], []
            else:
                return
        self.hist_t.append(t)
        self.hist_q.append((o.x, o.y, o.z, o.w))
        if len(self.hist_t) > 3000:                         # one minute at 50 Hz
            del self.hist_t[:1000], self.hist_q[:1000]

    def on_tick(self):
        now = self.now_s()
        ft = now - self.t0                                  # the flight's clock
        if ft > self.duration_s:
            if not self.loop:
                self.get_logger().info("flight finished (loop:=false); stop with Ctrl+C", once=True)
                return
            self.t0 += self.duration_s - self.start_s
            self.get_logger().info("the recorded flight starts again")
            self._restart_lap()
            return
        while self.publish_imu and self.i_imu < len(self.imu) and self.imu[self.i_imu][0] <= ft:
            t, q = self.imu[self.i_imu]
            m = Imu()
            m.header.stamp = s_to_stamp(self.t0 + t)
            m.header.frame_id = "base_link"
            m.orientation.x, m.orientation.y, m.orientation.z, m.orientation.w = (float(v) for v in q)
            self.pub_imu.publish(m)
            self.i_imu += 1
        while self.i_frame < len(self.frames) and self.frames[self.i_frame]["grab_s"] <= ft:
            f = self.frames[self.i_frame]
            arrival = self.t0 + f["grab_s"]
            if self.queue_len == 1:
                self.newest = (f, arrival)                   # grab every frame, keep the newest
            elif len(self.queue) < self.queue_len:
                self.queue.append((f, arrival))              # a full queue loses the new frame
            self.i_frame += 1
        if now >= self.next_offer:
            self.next_offer += 1.0 / self.rate_hz
            if self.next_offer < now:
                self.next_offer = now + 1.0 / self.rate_hz
            if self.queue_len == 1 and self.newest is not None:
                f, arrival = self.newest
                self.newest = None
                self.offer(f, grab=arrival, arrival=arrival, now=now)
            elif self.queue_len > 1 and self.queue:
                f, arrival = self.queue.popleft()
                self.offer(f, grab=now, arrival=arrival, now=now)

    def offer(self, f, grab, arrival, now):
        tm = self.timing
        exposure = exposure_time(grab, self.latency_s)
        try:
            q = tm.attitude_at(exposure, self.hist_t, self.hist_q, self.cfg["max_gap_s"])
            rate = tm.rotation_rate_dps(exposure, self.hist_t, self.hist_q, self.cfg["rate_window_s"],
                                        self.cfg["max_gap_s"])
            verdict = tm.usable(q, rate, self.cfg)
        except Exception as e:                               # a crash in one of YOUR functions
            self.get_logger().error(f"your timing.py failed: {type(e).__name__}: {e}", throttle_duration_sec=5.0)
            return
        if not (isinstance(verdict, (tuple, list)) and len(verdict) == 2):
            self.get_logger().error(f"usable() returned {verdict!r}, not (ok, reason): write TODO 6 (and TODO 4–5) of "
                                    "navera_lite/timing.py", throttle_duration_sec=5.0)
            return
        ok, reason = verdict
        if q is not None:
            roll, pitch_up, heading = rpy_human(q)
            att_err = q_angle_deg(q, f["q_true"])
            tilt = tilt_deg(q)
        else:
            roll = pitch_up = heading = tilt = att_err = math.nan
        values = {"frame": f["frame"], "grab_s": grab, "exposure_s": exposure, "latency_s": self.latency_s,
                  "waited_s": now - arrival, "roll_deg": roll, "pitch_up_deg": pitch_up, "heading_deg": heading,
                  "tilt_deg": tilt, "rate_dps": rate, "usable": bool(ok), "att_err_deg": att_err,
                  "queue": self.queue_len}
        img = self.painter.draw(f["east_m"], f["north_m"], f["height_m"], f["q_true"])
        im = Image()
        im.header.stamp = s_to_stamp(exposure)
        im.header.frame_id = "camera"
        im.height, im.width = img.shape[0], img.shape[1]
        im.encoding, im.step = "bgr8", 3 * img.shape[1]
        im.data = img.tobytes()
        self.pub_img.publish(im)
        meta = DiagnosticStatus(level=DiagnosticStatus.OK if ok else DiagnosticStatus.WARN, name=META_NAME,
                                message=str(reason), hardware_id="replay")
        meta.values = [KeyValue(key=k, value=nice(values[k], 6 if k.endswith("_s") else 3)) for k in META_KEYS]
        self.pub_meta.publish(meta)
        self.offered += 1
        waited = f", waited {now - arrival:.2f} s in the queue" if self.queue_len > 1 else ""
        self.get_logger().info(
            f"frame {f['frame']:3d}{waited}: roll {roll:5.1f}°, rate {nice(rate, 1):>5} °/s → "
            f"{'usable' if ok else 'REFUSED'} ({reason}); attitude error {att_err:.2f}°")
        if self.save_dir:
            os.makedirs(self.save_dir, exist_ok=True)
            cv2.imwrite(os.path.join(self.save_dir, "live_frame.jpg"), img)
            with open(os.path.join(self.save_dir, "live_meta.json"), "w") as fh:
                json.dump({"reason": str(reason), **{k: nice(values[k], 6) for k in META_KEYS}}, fh, indent=1)


# given — read it and use it, no need to change it
def main(args=None):
    """Start the camera node and spin until Ctrl+C."""
    run_node(CameraNode, args)


if __name__ == "__main__":
    main()
